import { useCallback, useRef, type ReactNode, type Ref } from 'react'
import { Checkbox as BaseCheckbox } from '@base-ui/react/checkbox'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import { ChoiceField, choiceStyles, type ValidationState } from './ChoiceField'
import styles from './Checkbox.module.css'

export interface CheckboxProps {
  ref?: Ref<HTMLElement>
  checked?: boolean
  defaultChecked?: boolean
  /** The spec's `onChange`. Base UI's event details are dropped. */
  onCheckedChange?: (checked: boolean) => void
  /** Neither checked nor unchecked: a "select all" with some selected. */
  isIndeterminate?: boolean
  label?: ReactNode
  helperText?: ReactNode
  name?: string
  /** Submitted when checked; "on" by default. */
  value?: string
  /** Colour of the checked box. */
  variant?: 'primary' | 'secondary' | 'neutral'
  disabled?: boolean
  required?: boolean
  readOnly?: boolean
  autoFocus?: boolean
  validationState?: ValidationState
  id?: string
  className?: string
  'aria-label'?: string
}

export function Checkbox({
  ref,
  autoFocus,
  label,
  helperText,
  name,
  variant = 'neutral',
  isIndeterminate,
  disabled,
  required,
  validationState,
  className,
  onCheckedChange,
  ...props
}: CheckboxProps) {
  // The root is a focusable <span>, and React only honours autoFocus on form
  // elements, so it is done by hand — once, on mount, not on every render.
  const focused = useRef(false)
  const setRef = useCallback(
    (node: HTMLElement | null) => {
      if (node && autoFocus && !focused.current) {
        focused.current = true
        node.focus()
      }
      if (typeof ref === 'function') ref(node)
      else if (ref) ref.current = node
    },
    [autoFocus, ref],
  )
  return (
    <ChoiceField
      label={label}
      helperText={helperText}
      validationState={validationState}
      required={required}
      disabled={disabled}
      name={name}
      className={className}
    >
      <BaseCheckbox.Root
        {...props}
        ref={setRef}
        indeterminate={isIndeterminate}
        required={required}
        onCheckedChange={onCheckedChange && ((next) => onCheckedChange(next))}
        className={cn(choiceStyles.control, styles.box, styles[variant])}
      >
        <BaseCheckbox.Indicator
          className={styles.indicator}
          render={(indicatorProps, state) => (
            <span {...indicatorProps}>
              <Icon name={state.indeterminate ? 'minus' : 'check'} />
            </span>
          )}
        />
      </BaseCheckbox.Root>
    </ChoiceField>
  )
}

/* 16px box, a --control-border outline (3:1 on the page) and the page
   colour inside. Checked and indeterminate fill with the variant. */
.box {
  --checkbox-fill: var(--foreground);
  --checkbox-mark: var(--background);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--space-4);
  block-size: var(--space-4);
  border: 1px solid var(--control-border);
  border-radius: var(--radius-sm);
  background: var(--background);
  cursor: var(--cursor-button);
}

.primary {
  --checkbox-fill: var(--primary);
  --checkbox-mark: var(--primary-foreground);
}

/* Secondary is the quiet one: a light fill with a dark mark, keeping the
   outline so the box stays visible. */
.secondary {
  --checkbox-fill: var(--secondary);
  --checkbox-mark: var(--secondary-foreground);
}

.box[data-checked],
.box[data-indeterminate] {
  border-color: var(--checkbox-fill);
  background: var(--checkbox-fill);
  color: var(--checkbox-mark);
}

.secondary[data-checked],
.secondary[data-indeterminate] {
  border-color: var(--control-border);
}

.box[data-invalid] {
  border-color: var(--danger-text);
}

.box[data-readonly] {
  cursor: default;
}

/* The mark is 14px in a 16px box: it has to read at a glance. */
.indicator {
  display: inline-flex;
  font-size: calc(var(--space-4) - 2px);
}
